declare(strict_types=1);require_once __DIR__.'/../../includes/api.php';cmsApiBootstrap();require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../includes/module-registry.php';$pdo=cmsPdo();if(!cmsModuleEnabled($pdo,'analytics'))cmsJson(['ok'=>false,'error'=>'MODULE_DISABLED'],404);if($_SERVER['REQUEST_METHOD']!=='POST')cmsJson(['ok'=>false,'error'=>'METHOD_NOT_ALLOWED'],405);$d=cmsRequestJson();$event=cmsStr($d['event_type']??'',40);$allowed=['page_view','section_view','item_view','conversion','whatsapp_click'];if(!in_array($event,$allowed,true))cmsJson(['ok'=>false,'error'=>'INVALID_EVENT'],422);$entityType=preg_replace('/[^a-z0-9_-]/','',strtolower(cmsStr($d['entity_type']??'',40)))??'';$entityId=max(0,cmsInt($d['entity_id']??0));$entityKey=cmsStr($d['entity_key']??'',120);$lang=in_array($d['language']??'',['ar','en'],true)?$d['language']:'';$q=$pdo->prepare('INSERT INTO analytics_daily(event_date,event_type,entity_type,entity_id,entity_key,language,event_count) VALUES(CURDATE(),:e,:t,:i,:k,:l,1) ON DUPLICATE KEY UPDATE event_count=event_count+1');$q->execute([':e'=>$event,':t'=>$entityType,':i'=>$entityId,':k'=>$entityKey,':l'=>$lang]);cmsJson(['ok'=>true]);
